package dev.vapor.transform.impl;

import dev.vapor.util.Insns;
import org.junit.jupiter.api.Test;
import org.objectweb.asm.ClassWriter;
import org.objectweb.asm.Opcodes;
import org.objectweb.asm.tree.InsnNode;
import org.objectweb.asm.tree.LabelNode;
import org.objectweb.asm.tree.MethodNode;

import java.lang.reflect.Method;
import java.util.Random;

import static org.junit.jupiter.api.Assertions.assertEquals;
/**
 * Proves the opaque predicate facts the empirical way: the generated bytecode
 * is loaded and executed over edge values and thousands of random ints. A form
 * that is not a true invariant for every int fails here (and in the worst case
 * would have silently altered program behavior).
 */
class OpaquePredicatesTest {

    private static final String HOST = "obf/test/PredicateHost";

    @Test
    void falseFormsNeverJump() throws Exception {
        Class<?> host = buildHost();
        for (int f = 0; f < OpaquePredicates.FALSE_FORMS; f++) {
            Method method = host.getMethod("f" + f, int.class);
            for (int v : edgeValues()) {
                assertEquals(Boolean.FALSE, method.invoke(null, v), "false form " + f + " on " + v);
            }
            Random random = new Random(42 + f);
            for (int i = 0; i < 5000; i++) {
                int v = random.nextInt();
                assertEquals(Boolean.FALSE, method.invoke(null, v), "false form " + f + " on " + v);
            }
        }
    }

    @Test
    void trueFormsAlwaysJump() throws Exception {
        Class<?> host = buildHost();
        for (int f = 0; f < OpaquePredicates.TRUE_FORMS; f++) {
            Method method = host.getMethod("t" + f, int.class);
            for (int v : edgeValues()) {
                assertEquals(Boolean.TRUE, method.invoke(null, v), "true form " + f + " on " + v);
            }
            Random random = new Random(1337 + f);
            for (int i = 0; i < 5000; i++) {
                int v = random.nextInt();
                assertEquals(Boolean.TRUE, method.invoke(null, v), "true form " + f + " on " + v);
            }
        }
    }

    @Test
    void zeroFormsYieldZero() throws Exception {
        Class<?> host = buildHost();
        for (int f = 0; f < OpaquePredicates.ZERO_FORMS; f++) {
            Method method = host.getMethod("z" + f, int.class);
            for (int v : edgeValues()) {
                assertEquals(0, ((Number) method.invoke(null, v)).intValue(), "zero form " + f + " on " + v);
            }
            Random random = new Random(7 + f);
            for (int i = 0; i < 5000; i++) {
                int v = random.nextInt();
                assertEquals(0, ((Number) method.invoke(null, v)).intValue(), "zero form " + f + " on " + v);
            }
        }
    }

    private static int[] edgeValues() {
        return new int[]{
                Integer.MIN_VALUE, Integer.MIN_VALUE + 1, Integer.MIN_VALUE + 2,
                -100000, -65536, -46341, -46340, -256, -3, -2, -1,
                0, 1, 2, 3, 5, 100, 255, 256, 46340, 46341, 65535, 65536, 100000,
                Integer.MAX_VALUE - 2, Integer.MAX_VALUE - 1, Integer.MAX_VALUE
        };
    }

    private static Class<?> buildHost() {
        ClassWriter cw = new ClassWriter(ClassWriter.COMPUTE_FRAMES | ClassWriter.COMPUTE_MAXS);
        cw.visit(Opcodes.V1_8, Opcodes.ACC_PUBLIC | Opcodes.ACC_FINAL, HOST, null, "java/lang/Object", null);

        for (int f = 0; f < OpaquePredicates.FALSE_FORMS; f++) {
            MethodNode method = new MethodNode(Opcodes.ASM9,
                    Opcodes.ACC_PUBLIC | Opcodes.ACC_STATIC, "f" + f, "(I)Z", null, null);
            LabelNode taken = new LabelNode();
            OpaquePredicates.jumpFalse(method.instructions, 0, f, taken);
            method.instructions.add(Insns.intNode(0));
            method.instructions.add(new InsnNode(Opcodes.IRETURN));
            method.instructions.add(taken);
            method.instructions.add(Insns.intNode(1));
            method.instructions.add(new InsnNode(Opcodes.IRETURN));
            accept(method, cw);
        }
        for (int f = 0; f < OpaquePredicates.TRUE_FORMS; f++) {
            MethodNode method = new MethodNode(Opcodes.ASM9,
                    Opcodes.ACC_PUBLIC | Opcodes.ACC_STATIC, "t" + f, "(I)Z", null, null);
            LabelNode taken = new LabelNode();
            OpaquePredicates.jumpTrue(method.instructions, 0, f, taken);
            method.instructions.add(Insns.intNode(0));
            method.instructions.add(new InsnNode(Opcodes.IRETURN));
            method.instructions.add(taken);
            method.instructions.add(Insns.intNode(1));
            method.instructions.add(new InsnNode(Opcodes.IRETURN));
            accept(method, cw);
        }
        for (int f = 0; f < OpaquePredicates.ZERO_FORMS; f++) {
            MethodNode method = new MethodNode(Opcodes.ASM9,
                    Opcodes.ACC_PUBLIC | Opcodes.ACC_STATIC, "z" + f, "(I)I", null, null);
            OpaquePredicates.pushZero(method.instructions, 0, f);
            method.instructions.add(new InsnNode(Opcodes.IRETURN));
            accept(method, cw);
        }

        cw.visitEnd();
        byte[] bytes = cw.toByteArray();
        return new Loader().define(bytes);
    }

    /** MethodNode maxs left at 0 on purpose: COMPUTE_FRAMES must fill them in. */
    private static void accept(MethodNode method, org.objectweb.asm.ClassVisitor visitor) {
        method.accept(visitor);
    }

    private static final class Loader extends ClassLoader {
        Class<?> define(byte[] bytes) {
            return defineClass(HOST.replace('/', '.'), bytes, 0, bytes.length);
        }
    }
}
